extern import asyncio
extern runAsync: (Async a) -> a = asyncio.run
extern type Queue
extern newQueue: unit -> Queue = asyncio.Queue
extern post: Queue -> a -> unit = .put_nowait
extern take: Queue -> Async a = .get()
type Msg = Said string | Tick | Quit
let heard count s =
    (print f"agent heard {s}")
    (count + 1)
let finished count = async { return count }
let agentLoop inbox count = async { let! msg = (take inbox) return! (match msg: case (Said s): ((agentLoop inbox) ((heard count) s)) case Tick: ((agentLoop inbox) count) case Quit: (finished count)) }
let producer inbox = async {
    for s in ["hello", "world"]:
        do! (Async.sleep 0.01)
        let _ = ((post inbox) (Said s))
    let _ = ((post inbox) Tick)
    let _ = ((post inbox) Quit)
}
let session = (Task.scope async { let inbox = (newQueue ()) let _ = (Task.start (producer inbox)) let! count = ((agentLoop inbox) 0) return count })
let count = (runAsync session)
(print f"agent handled {count} messages")
